// FUNÇÕES UTILITÁRIAS
// ============================================================
function isFileType(i, e) {
    return FILE_TYPES[e] && FILE_TYPES[e].includes(i?.toLowerCase());
}

function getFileIcon(i) {
    const e = i?.toLowerCase();
    return isFileType(e, "video") ? '<i class="bi bi-camera-video-fill gdi-icon-video"></i>' :
           isFileType(e, "audio") ? '<i class="bi bi-music-note-beamed gdi-icon-audio"></i>' :
           isFileType(e, "image") ? '<i class="bi bi-image gdi-icon-image"></i>' :
           isFileType(e, "archive") ? '<i class="bi bi-file-earmark-zip-fill gdi-icon-archive"></i>' :
           isFileType(e, "markdown") ? '<i class="bi bi-markdown-fill gdi-icon-md"></i>' :
           e === "pdf" ? '<i class="bi bi-file-earmark-pdf-fill gdi-icon-pdf"></i>' :
           isFileType(e, "code") ? '<i class="bi bi-code-slash gdi-icon-code"></i>' :
           '<i class="bi bi-file-earmark gdi-icon-file"></i>';
}

function generateBreadcrumb(i) {
    const e = i.split("/");
    let t = "", n = "";
    for (let a = 0; a < e.length; a++) {
        let c = e[a];
        n += (a === 0 ? "" : "/") + c;
        const l = a === e.length - 1;
        let d;
        try { d = decodeURIComponent(c); } catch { d = c; }
        const o = d.match(/^(\d+):$/);
        const s = o ? window.drive_names && window.drive_names[+o[1]] || d : d || "Home";
        const r = s.length > 20 ? s.slice(0, 16) + "\u2026" : s;
        if (l) {
            t += `<li class="gdi-bc-cur" title="${escHtml(s)}">${escHtml(r)}</li>`;
        } else {
            t += `<li><a href="${n ? n + "/" : "/"}" title="${escHtml(s)}">${escHtml(r)}</a></li><li class="gdi-bc-sep">/</li>`;
        }
    }
    return t;
}

const Os = {
    isWindows: navigator.userAgent.toUpperCase().indexOf("WIN") > -1,
    isMac: navigator.userAgent.toUpperCase().indexOf("MAC") > -1,
    isMacLike: /(Mac|iPhone|iPod|iPad)/i.test(navigator.userAgent),
    isIos: /(iPhone|iPod|iPad)/i.test(navigator.userAgent),
    isMobile: /Android|webOS|iPhone|iPad|iPod|iOS|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)
};

function getDocumentHeight() {
    const i = document;
    return Math.max(
        i.body.scrollHeight,
        i.documentElement.scrollHeight,
        i.body.offsetHeight,
        i.documentElement.offsetHeight,
        i.body.clientHeight,
        i.documentElement.clientHeight
    );
}

function getQueryVariable(i) {
    const t = window.location.search.substring(1).split("&");
    for (let n = 0; n < t.length; n++) {
        const a = t[n].split("=");
        if (a[0] == i) return a.slice(1).join("=");
    }
    return false;
}

function escHtml(i) {
    return String(i)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#x27;");
}

function trimChar(i, e) {
    return e ? i.replace(new RegExp("^\\" + e + "+|\\" + e + "+$", "g"), "") : i.trim();
}

function applyTheme(i) {
    document.documentElement.setAttribute("data-bs-theme", i);
    const e = document.getElementById("theme-icon");
    e && (e.className = i === "dark" ? "bi bi-moon-stars" : "bi bi-sun");
}

function toggleTheme() {
    const e = (document.documentElement.getAttribute("data-bs-theme") || "dark") === "dark" ? "light" : "dark";
    localStorage.setItem("gdi-theme", e);
    applyTheme(e);
    GDIUserSystem.updatePreferences({theme: e});
}

function sleep(i) {
    return new Promise(e => setTimeout(e, i));
}

function formatFileSize(i) {
    const e = Number(i);
    return isNaN(e) || e < 0 ? "" :
           e >= 1099511627776 ? (e / 1099511627776).toFixed(2) + " TB" :
           e >= 1073741824 ? (e / 1073741824).toFixed(2) + " GB" :
           e >= 1048576 ? (e / 1048576).toFixed(2) + " MB" :
           e >= 1024 ? (e / 1024).toFixed(2) + " KB" :
           e > 1 ? e + " bytes" :
           e === 1 ? "1 byte" : "0 bytes";
}

function formatDateTime(i) {
    return i ? new Date(i).toLocaleString() : "";
}
const utc2delhi = formatDateTime;

function formatTime(seconds) {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = Math.floor(seconds % 60);
    
    if (h > 0) {
        return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    }
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

