function title(i) {
    try { i = decodeURI(i); } catch {}
    const e = window.current_drive_order || 0;
    const t = (window.drive_names && window.drive_names[e]) || "Drive";
    i = i.replace(`/${e}:`, "");
    const n = window.MODEL || {};
    n.is_search_page ? $("title").html(`${t} - Search: ${n.q || ""}`) : $("title").html(`${t} - ${i}`);
}

function nav(i) {
    const e = window.MODEL || {};
    const t = window.current_drive_order || 0;
    const n = (window.drive_names && window.drive_names[t]) || "Drive";
    const a = window.drive_names || [];
    const UI = window.UI || {};
    const c = e.is_search_page && e.q || "";
    
    let l = "";
    a.forEach((r, p) => {
        l += `<li><a class="dropdown-item${p === t ? " active" : ""}" href="/${p}:/">
          <i class="bi bi-folder2-open"></i> ${r}</a></li>`;
    });
    
    const d = UI.logo_image ? `<img src="${UI.logo_link_name}" alt="${UI.company_name}" height="28">` : `<i class="bi bi-cloud-fill"></i> ${UI.logo_link_name}`;
    const o = (e.root_type === undefined || e.root_type < 2) ? `
      <div class="gdi-nav-search">
        <form class="gdi-search-form" method="get" action="/${t}:search">
          <input class="gdi-search-input" name="q" type="search" placeholder="Search files…" value="${escHtml(c)}">
          <button class="gdi-search-btn" type="submit"><i class="bi bi-search"></i></button>
        </form>
      </div>` : "";
    
    const s = `
    <nav class="gdi-nav">
      <div class="gdi-nav-inner">
        <a class="gdi-logo" href="/${t}:/">${d}</a>
        <div class="gdi-nav-sep"></div>
        ${o}
        <div class="gdi-nav-actions">
          <div class="dropdown">
            <button class="gdi-nav-btn dropdown-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false">
              <i class="bi bi-grid-3x3-gap-fill"></i>
              <span class="d-none d-md-inline">${escHtml(n)}</span>
            </button>
            <ul class="dropdown-menu dropdown-menu-end">${l}</ul>
          </div>
          <div class="gdi-nav-sep"></div>
          <button id="theme-toggle" class="gdi-nav-btn" onclick="toggleTheme()" title="Toggle theme">
            <i class="bi bi-moon-stars" id="theme-icon"></i>
          </button>
          ${UI.show_logout_button ? '<a class="gdi-nav-btn" href="/logout" title="Logout"><i class="bi bi-box-arrow-right"></i></a>' : ""}
        </div>
      </div>
    </nav>`;
    
    $("#nav").html(s);
    applyTheme(localStorage.getItem("gdi-theme") || "dark");
}

function render(i) {
    if (i.indexOf("?") >= 0) {
        i = i.substr(0, i.indexOf("?"));
    }
    title(i);
    nav(i);
    
    const e = /\/\d+:$/g;
    if (i.includes("/fallback")) {
        window.scroll_status = {event_bound: false, loading_lock: false};
        const t = getQueryVariable("a");
        const n = decodeURIComponent(getQueryVariable("id") || "");
        return t ? fallback(n, true) : list(null, n, true);
    } else if (window.MODEL?.is_search_page) {
        window.scroll_status = {event_bound: false, loading_lock: false};
        render_search_result_list();
    } else if (i.match(e) || i.slice(-1) == "/") {
        window.scroll_status = {event_bound: false, loading_lock: false};
        list(i);
    } else {
        file(i);
    }
}

