// FUNÇÕES DE LISTAGEM
// ============================================================
function requestListPath(i, e, t, n, a = 3, c = false) {
    const l = {
        id: e.id || "",
        type: "folder",
        password: e.password || "",
        page_token: e.page_token || "",
        page_index: e.page_index || 0
    };
    const d = a != null && a >= 0 ? a : 3;
    
    $("#update").show();
    $("#update").html('<div class="gdi-alert gdi-alert-info">Connecting…</div>');
    c && (i = "/0:fallback");
    
    async function o(s) {
        try {
            const r = await fetch(c ? "/0:fallback" : i, {
                method: "POST",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify(l)
            });
            if (!r.ok) throw new Error("Request failed with status " + r.status);
            const p = await r.json();
            
            if (p && p.error && p.error.code === 401) {
                $("#update").hide();
                askPassword(i);
            } else if (p && p.data === null) {
                document.getElementById("spinner")?.remove();
                $("#list").html(`<div class="gdi-empty"><i class="bi bi-exclamation-circle"></i><p>Server didn't send any data.</p></div>`);
                $("#update").hide();
            } else if (p && p.data) {
                t(p, i, l);
                $("#update").hide();
            }
        } catch (r) {
            if (s > 0) {
                $("#update").html(`<div class="gdi-alert gdi-alert-info">Retrying… (${s} left)</div>`);
                await sleep(2000);
                await o(s - 1);
            } else {
                $("#update").html('<div class="gdi-alert gdi-alert-error">Unable to connect. Please try again.</div>');
                $("#list").html(`<div class="gdi-empty"><i class="bi bi-wifi-off"></i><p>${escHtml(String(r))}</p></div>`);
                $("#update").hide();
            }
        }
    }
    
    o(d);
}

function requestSearch(i, e, t = 3) {
    const n = {
        q: i.q || null,
        page_token: i.page_token || null,
        page_index: i.page_index || 0
    };
    
    async function a(c) {
        try {
            const l = await fetch(`/${window.current_drive_order || 0}:search`, {
                method: "POST",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify(n)
            });
            if (!l.ok) throw new Error("Request failed with status " + l.status);
            const d = await l.json();
            
            if (d && d.data === null) {
                $("#spinner").remove();
                $("#list").html('<div class="gdi-empty"><i class="bi bi-search"></i><p>No results found.</p></div>');
                $("#update").remove();
            } else if (d && d.data) {
                e && e(d, n);
                $("#update").remove();
            }
        } catch {
            if (c > 0) {
                $("#update").html(`<div class="gdi-alert gdi-alert-info">Retrying… (${c} left)</div>`);
                await sleep(2000);
                await a(c - 1);
            } else {
                $("#update").html(`<div class="gdi-alert gdi-alert-error">Unable to connect after ${t} attempts.</div>`);
                $("#list").html('<div class="gdi-empty"><i class="bi bi-wifi-off"></i><p>Connection failed.</p></div>');
                $("#spinner").remove();
            }
        }
    }
    
    $("#update").html('<div class="gdi-alert gdi-alert-info">Searching…</div>');
    a(t);
}

function list(i, e = "", t = false) {
    const n = window.location.pathname;
    const a = trimChar(n, "/").split("/");
    let c = "/";
    let l = '<li><a href="/">Home</a></li><li class="gdi-bc-sep">/</li>';
    
    if (a.length > 1) {
        for (const p in a) {
            const g = a[p];
            let f;
            try { f = decodeURIComponent(g); } catch { f = g; }
            f = f.replace(/\//g, "%2F");
            const u = f.match(/^(\d+):$/);
            const h = u && window.drive_names && window.drive_names[+u[1]] || f;
            const m = h.length > 18 ? h.slice(0, 14) + "…" : h;
            
            c += g + "/";
            if (!m) break;
            
            if (Number(p) === a.length - 1) {
                l += `<li class="gdi-bc-cur" title="${escHtml(h)}">${escHtml(m)}</li>`;
            } else {
                l += `<li><a href="${c}" title="${escHtml(h)}">${escHtml(m)}</a></li><li class="gdi-bc-sep">/</li>`;
            }
        }
    }
    
    const d = `
    <div class="gdi-wrap">
      <div id="update"></div>
      <div id="head_md" class="gdi-panel gdi-markdown" style="display:none;"></div>
      <div id="select_items" class="gdi-select-bar" style="display:none;">
        <label style="display:flex;align-items:center;gap:6px;cursor:pointer;">
          <input type="checkbox" id="select-all-checkboxes"> Select all
        </label>
        <button id="handle-multiple-items-copy" class="gdi-btn gdi-btn-ghost">
          <i class="bi bi-clipboard"></i> Copy selected
        </button>
      </div>
      <div class="gdi-breadcrumb-wrap">
        <ol class="gdi-bc" id="folderne">${l}</ol>
      </div>
      <div class="gdi-panel">
        <div class="gdi-toolbar">
          <input id="folder-filter" class="gdi-filter-input" type="search" placeholder="Filter files…" autocomplete="off">
        </div>
        <div class="gdi-list-header" id="list-header">
          <span class="gdi-col-name gdi-sort-header" data-sort="name">Name</span>
          <span class="gdi-col-size gdi-sort-header" data-sort="size">Size</span>
          <span class="gdi-col-date gdi-sort-header" data-sort="date">Modified</span>
          <span class="gdi-col-acts"></span>
        </div>
        <div id="list"></div>
        <div id="count" class="gdi-count-bar"></div>
      </div>
      <div id="readme_md" class="gdi-panel gdi-markdown" style="display:none;"></div>
    </div>`;
    
    $("#content").html(d);
    
    // Adicionar banner "Continuar Assistindo"
    addContinueWatchingBanner();
    
    const o = localStorage.getItem("password" + i);
    $("#list").html('<div class="gdi-spinner-wrap" id="spinner"><div class="gdi-spinner"></div></div>');
    $("#readme_md").hide().html("");
    $("#head_md").hide().html("");
    
    function s(p, g, f) {
        $("#list").data("nextPageToken", p.nextPageToken).data("curPageIndex", p.curPageIndex);
        $("#spinner").remove();
        
        if (p.nextPageToken === null) {
            $(window).off("scroll");
            window.scroll_status.event_bound = false;
            window.scroll_status.loading_lock = false;
            t ? append_files_to_fallback_list(g, p.data.files) : append_files_to_list(g, p.data.files);
        } else {
            t ? append_files_to_fallback_list(g, p.data.files) : append_files_to_list(g, p.data.files);
            
            if (window.scroll_status.event_bound !== true) {
                $(window).on("scroll", function() {
                    if ($(this).scrollTop() + $(this).height() > getDocumentHeight() - (Os.isMobile ? 130 : 80)) {
                        if (window.scroll_status.loading_lock === true) return;
                        window.scroll_status.loading_lock = true;
                        $('<div id="spinner" class="gdi-spinner-wrap"><div class="gdi-spinner"></div></div>').insertBefore("#readme_md");
                        const u = $("#list");
                        
                        t ? requestListPath(g, {
                            id: e,
                            password: f.password,
                            page_token: u.data("nextPageToken"),
                            page_index: u.data("curPageIndex") + 1
                        }, s, null, 5, true) : requestListPath(g, {
                            password: f.password,
                            page_token: u.data("nextPageToken"),
                            page_index: u.data("curPageIndex") + 1
                        }, s, null);
                    }
                });
                window.scroll_status.event_bound = true;
            }
        }
        
        if (window.scroll_status.loading_lock === true) {
            window.scroll_status.loading_lock = false;
        }
    }
    
    t ? requestListPath(i, {id: e, password: o}, s, null, 3, true) : requestListPath(i, {password: o}, s, null);
    
    const r = document.getElementById("handle-multiple-items-copy");
    r && r.addEventListener("click", () => {
        const p = document.querySelectorAll("input.gdi-row-check:checked");
        if (!p.length) {
            alert("No items selected!");
            return;
        }
        const g = Array.from(p).map(f => f.value).join("\n");
        navigator.clipboard.writeText(g).catch(() => {
            const f = document.createElement("textarea");
            f.value = g;
            document.body.appendChild(f);
            f.select();
            document.execCommand("copy");
            document.body.removeChild(f);
        });
        showToast(`${p.length} link${p.length > 1 ? "s" : ""} copied`);
    });
}

// Banner "Continuar Assistindo"
function addContinueWatchingBanner() {
    const continueWatching = GDIUserSystem.getContinueWatching();
    if (continueWatching.length === 0) return;
    
    const bannerHTML = `
    <div class="gdi-continue-watching" style="margin-bottom:16px;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
            <strong style="font-size:14px;"><i class="bi bi-clock-history me-2"></i>Continuar Assistindo</strong>
        </div>
        <div style="display:flex;gap:12px;overflow-x:auto;padding-bottom:8px;">
            ${continueWatching.map(item => `
                <div style="min-width:200px;background:rgba(0,0,0,0.2);border-radius:8px;padding:12px;cursor:pointer;" 
                     onclick="resumeVideo('${item.videoId}')">
                    <div style="font-size:13px;font-weight:600;margin-bottom:8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">
                        ${escHtml(item.name)}
                    </div>
                    <div style="height:4px;background:rgba(255,255,255,0.1);border-radius:2px;overflow:hidden;margin-bottom:8px;">
                        <div style="height:100%;width:${item.progress * 100}%;background:#1f6feb;border-radius:2px;"></div>
                    </div>
                    <div style="font-size:11px;color:#8b949e;">
                        ${Math.round(item.progress * 100)}% assistido
                    </div>
                </div>
            `).join('')}
        </div>
    </div>`;
    
    const breadcrumb = document.querySelector('.gdi-breadcrumb-wrap');
    if (breadcrumb && !document.querySelector('.gdi-continue-watching')) {
        breadcrumb.insertAdjacentHTML('beforebegin', bannerHTML);
    }
}

function resumeVideo(videoId) {
    const progress = GDIUserSystem.getVideoProgress(videoId);
    if (progress && progress.url) {
        window.location.href = progress.url;
        showToast(`Retomando "${progress.name}" de ${formatTime(progress.currentTime)}`);
    }
}

function askPassword(i) {
    $("#spinner").remove();
    const e = prompt("This folder is password protected. Enter the password:", "");
    e != null && e != "" ? (localStorage.setItem("password" + i, e), list(i)) : history.go(-1);
}

let _folderFilterBound = false;
function initFolderFilter() {
    const i = document.getElementById("folder-filter");
    !i || _folderFilterBound || (_folderFilterBound = true, i.addEventListener("input", function() {
        const e = this.value.toLowerCase();
        document.querySelectorAll("#list .gdi-row").forEach(t => {
            const n = (t.dataset.name || t.textContent).toLowerCase();
            t.style.display = !e || n.includes(e) ? "" : "none";
        });
    }));
}

let _sortState = {col: null, dir: 1};
function initColumnSort() {
    const i = document.querySelectorAll("#list-header .gdi-sort-header");
    i.forEach(e => {
        e.addEventListener("click", function() {
            const t = this.dataset.sort;
            _sortState.col === t ? _sortState.dir *= -1 : (_sortState.col = t, _sortState.dir = 1);
            i.forEach(n => n.classList.remove("asc", "desc"));
            this.classList.add(_sortState.dir === 1 ? "asc" : "desc");
            sessionStorage.setItem("gdi-sort", JSON.stringify(_sortState));
            sortFileList(t, _sortState.dir);
        });
    });
    
    try {
        const e = JSON.parse(sessionStorage.getItem("gdi-sort"));
        e && e.col && (_sortState = e);
    } catch {}
}

function sortFileList(i, e) {
    const t = $("#list");
    const n = t.children(".gdi-row").toArray();
    n.sort((a, c) => {
        if (i === "size") return e * ((parseFloat($(a).data("bytes")) || 0) - (parseFloat($(c).data("bytes")) || 0));
        if (i === "date") return e * (new Date($(a).data("date")) - new Date($(c).data("date")));
        const l = ($(a).data("name") || "").toLowerCase();
        const d = ($(c).data("name") || "").toLowerCase();
        return e * l.localeCompare(d);
    });
    n.forEach(a => t.append(a));
}

