// ============================================================
// POMODORO TIMER
// ============================================================
function initPomodoroOnce() {
    if (window.__gdiPomodoroBooted) return;
    window.__gdiPomodoroBooted = true;
    
    const CSS = `
#gdi-pom-root{position:fixed;bottom:76px;right:16px;z-index:10000;font-family:inherit;}
#gdi-pom-fab{width:46px;height:46px;border-radius:50%;background:rgba(18,18,28,0.95);border:2px solid rgba(255,255,255,0.15);
  box-shadow:0 4px 18px rgba(0,0,0,0.55);cursor:pointer;display:flex;align-items:center;justify-content:center;
  font-size:22px;transition:transform 0.18s,box-shadow 0.18s;user-select:none;}
#gdi-pom-fab:hover{transform:scale(1.1);box-shadow:0 6px 24px rgba(0,0,0,0.7);}
#gdi-pom-fab .gdi-pom-fab-ring{position:absolute;inset:-3px;border-radius:50%;border:2.5px solid transparent;transition:border-color 0.4s;}
#gdi-pom-fab .gdi-pom-fab-time{position:absolute;bottom:-14px;left:50%;transform:translateX(-50%);
  font-size:9px;font-weight:700;color:#f0f6fc;white-space:nowrap;letter-spacing:.04em;
  background:rgba(18,18,28,0.85);padding:1px 5px;border-radius:6px;}
#gdi-pom-panel{position:absolute;bottom:58px;right:0;width:230px;
  background:rgba(14,14,22,0.97);border:1.5px solid rgba(255,255,255,0.13);border-radius:14px;
  box-shadow:0 10px 40px rgba(0,0,0,0.6);padding:14px 16px 12px;
  transform-origin:bottom right;transform:scale(0.85);opacity:0;pointer-events:none;
  transition:transform 0.18s cubic-bezier(.4,0,.2,1),opacity 0.18s;}
#gdi-pom-panel.open{transform:scale(1);opacity:1;pointer-events:all;}
.gdi-pom-phase-label{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;margin-bottom:6px;text-align:center;}
#gdi-pom-display{font-size:44px;font-weight:800;text-align:center;color:#f0f6fc;letter-spacing:.05em;font-variant-numeric:tabular-nums;line-height:1;}
#gdi-pom-progress{height:4px;background:rgba(255,255,255,0.1);border-radius:2px;margin:10px 0 8px;overflow:hidden;}
#gdi-pom-progress-bar{height:4px;border-radius:2px;width:100%;transition:width 1s linear,background 0.4s;}
#gdi-pom-sessions-dots{display:flex;gap:5px;justify-content:center;margin-bottom:10px;}
.gdi-pom-dot{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,0.15);transition:background 0.3s;}
.gdi-pom-dot.done{background:#1f6feb;}
#gdi-pom-btns{display:flex;gap:6px;justify-content:center;margin-bottom:8px;}
.gdi-pom-btn{background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.13);color:#e6edf3;
  border-radius:7px;padding:5px 11px;cursor:pointer;font-size:12px;transition:background 0.15s;white-space:nowrap;}
.gdi-pom-btn:hover{background:rgba(255,255,255,0.2);}
.gdi-pom-btn:disabled{opacity:0.35;cursor:default;}
#gdi-pom-divider{height:1px;background:rgba(255,255,255,0.08);margin:8px 0;}
#gdi-pom-cfg{display:flex;flex-direction:column;gap:5px;}
.gdi-pom-cfg-row{display:flex;align-items:center;justify-content:space-between;font-size:11px;color:#8b949e;}
.gdi-pom-cfg-row input{width:42px;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.13);
  border-radius:5px;color:#f0f6fc;text-align:center;padding:2px 4px;font-size:11px;}
#gdi-pom-sync-label{font-size:10px;color:#8b949e;text-align:center;margin-top:6px;}
#gdi-pom-flash{position:fixed;inset:0;z-index:9999;pointer-events:none;opacity:0;transition:opacity 0.15s;}
@keyframes gdi-pom-pulse{0%,100%{box-shadow:0 4px 18px rgba(0,0,0,0.55);}50%{box-shadow:0 0 0 10px rgba(255,100,100,0.25),0 4px 18px rgba(0,0,0,0.55);}}
#gdi-pom-fab.warning{animation:gdi-pom-pulse 0.8s ease-in-out infinite;}
`;
    
    const styleEl = document.createElement('style');
    styleEl.textContent = CSS;
    document.head.appendChild(styleEl);
    
    const flashEl = document.createElement('div');
    flashEl.id = 'gdi-pom-flash';
    document.body.appendChild(flashEl);
    
    const root = document.createElement('div');
    root.id = 'gdi-pom-root';
    root.innerHTML = `
    <div id="gdi-pom-fab" title="Pomodoro">
      <div class="gdi-pom-fab-ring" id="gdi-pom-fab-ring"></div>
      <span>🍅</span>
      <span class="gdi-pom-fab-time" id="gdi-pom-fab-time">25:00</span>
    </div>
    <div id="gdi-pom-panel">
      <div class="gdi-pom-phase-label" id="gdi-pom-phase-label">🍅 FOCO</div>
      <div id="gdi-pom-display">25:00</div>
      <div id="gdi-pom-progress"><div id="gdi-pom-progress-bar"></div></div>
      <div id="gdi-pom-sessions-dots"></div>
      <div id="gdi-pom-btns">
        <button class="gdi-pom-btn" id="gdi-pom-start">▶ Iniciar</button>
        <button class="gdi-pom-btn" id="gdi-pom-skip">⏭</button>
        <button class="gdi-pom-btn" id="gdi-pom-reset">↺</button>
      </div>
      <div id="gdi-pom-sync-label">⏱ Sincroniza com o player</div>
      <div id="gdi-pom-divider"></div>
      <div id="gdi-pom-cfg">
        <div class="gdi-pom-cfg-row"><span>🍅 Foco (min)</span><input id="gdi-pom-c-work" type="number" min="1" max="90" value="25"></div>
        <div class="gdi-pom-cfg-row"><span>☕ Pausa curta</span><input id="gdi-pom-c-short" type="number" min="1" max="30" value="5"></div>
        <div class="gdi-pom-cfg-row"><span>🛋 Pausa longa</span><input id="gdi-pom-c-long" type="number" min="1" max="60" value="15"></div>
        <div class="gdi-pom-cfg-row"><span>🔁 Sessões p/ longa</span><input id="gdi-pom-c-sess" type="number" min="1" max="10" value="4"></div>
      </div>
    </div>
  `;
    document.body.appendChild(root);
    
    let cfg = {work: 25, short: 5, long: 15, sessions: 4};
    try {
        const saved = JSON.parse(localStorage.getItem('gdi-pom-cfg') || '{}');
        if (saved.work) cfg = {...cfg, ...saved};
    } catch (e) {}
    
    let phase = 'work', totalSecs = cfg.work * 60, remainSecs = cfg.work * 60;
    let running = false, timer = null, completedSessions = 0;
    let panelOpen = false, playerSynced = false;
    
    document.getElementById('gdi-pom-c-work').value = cfg.work;
    document.getElementById('gdi-pom-c-short').value = cfg.short;
    document.getElementById('gdi-pom-c-long').value = cfg.long;
    document.getElementById('gdi-pom-c-sess').value = cfg.sessions;
    
    function beep(freq = 880, dur = 0.3, type = 'sine', vol = 0.4) {
        try {
            const ctx = new (window.AudioContext || window.webkitAudioContext)();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.type = type;
            osc.frequency.value = freq;
            gain.gain.setValueAtTime(vol, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + dur);
            osc.start();
            osc.stop(ctx.currentTime + dur);
        } catch (e) {}
    }
    
    function playAlarm(isBreak) {
        const notes = isBreak ? [660, 880, 1100] : [1100, 880, 660];
        notes.forEach((f, i) => setTimeout(() => beep(f, 0.4, 'sine', 0.5), i * 300));
    }
    
    function playWarningBeep(secondsLeft) {
        beep(880 + (10 - secondsLeft) * 20, 0.12, 'square', 0.3);
    }
    
    function flash(color) {
        flashEl.style.background = color;
        flashEl.style.opacity = '0.4';
        setTimeout(() => { flashEl.style.opacity = '0'; }, 600);
    }
    
    function fmt(s) {
        return String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');
    }
    
    function phaseInfo() {
        if (phase === 'work') return {label: '🍅 FOCO', color: '#1f6feb', ringColor: '#1f6feb', flashColor: '#001a40'};
        if (phase === 'short') return {label: '☕ PAUSA', color: '#2f9e44', ringColor: '#2f9e44', flashColor: '#002a10'};
        return {label: '🛋 PAUSA LONGA', color: '#7048e8', ringColor: '#7048e8', flashColor: '#1a0040'};
    }
    
    function buildDots() {
        const el = document.getElementById('gdi-pom-sessions-dots');
        if (!el) return;
        
        let h = '';
        const sessionsInCycle = completedSessions % cfg.sessions;
        
        for (let i = 0; i < cfg.sessions; i++) {
            const done = i < sessionsInCycle;
            h += `<div class="gdi-pom-dot${done ? ' done' : ''}"></div>`;
        }
        el.innerHTML = h;
    }
    
    function updateUI() {
        const info = phaseInfo();
        const timeStr = fmt(remainSecs);
        const pct = remainSecs / totalSecs * 100;
        const warn = remainSecs <= 10 && remainSecs > 0;
        
        document.getElementById('gdi-pom-display').textContent = timeStr;
        document.getElementById('gdi-pom-display').style.color = warn ? '#ff6b6b' : '#f0f6fc';
        document.getElementById('gdi-pom-phase-label').textContent = info.label;
        document.getElementById('gdi-pom-phase-label').style.color = info.color;
        
        const bar = document.getElementById('gdi-pom-progress-bar');
        bar.style.width = pct + '%';
        bar.style.background = warn ? '#ff6b6b' : info.color;
        
        document.getElementById('gdi-pom-fab-time').textContent = timeStr;
        document.getElementById('gdi-pom-fab-time').style.color = warn ? '#ff6b6b' : '#f0f6fc';
        document.getElementById('gdi-pom-fab-ring').style.borderColor = running ? info.ringColor : 'transparent';
        
        const fab = document.getElementById('gdi-pom-fab');
        warn && running ? fab.classList.add('warning') : fab.classList.remove('warning');
        
        document.getElementById('gdi-pom-start').textContent = running ? '⏸ Pausar' : '▶ ' + (remainSecs < totalSecs ? 'Continuar' : 'Iniciar');
        
        buildDots();
        
        if (running) {
            const origTitle = document.siteName || 'GDI';
            document.title = `${timeStr} ${info.label} | ${origTitle}`;
        }
    }
    
    function startTimer() {
        clearInterval(timer);
        running = true;
        timer = setInterval(() => {
            if (remainSecs <= 0) {
                nextPhase();
                return;
            }
            remainSecs--;
            if (remainSecs <= 10 && remainSecs > 0) playWarningBeep(remainSecs);
            updateUI();
        }, 1000);
        updateUI();
    }
    
    function pauseTimer() {
        clearInterval(timer);
        running = false;
        updateUI();
        document.title = document.siteName || 'GDI';
    }
    
    function resetTimer() {
        pauseTimer();
        phase = 'work';
        totalSecs = cfg.work * 60;
        remainSecs = totalSecs;
        completedSessions = 0;
        updateUI();
    }
    
    function nextPhase() {
        clearInterval(timer);
        running = false;
        
        if (phase === 'work') {
            completedSessions++;
            const isLongBreak = completedSessions % cfg.sessions === 0;
            phase = isLongBreak ? 'long' : 'short';
            totalSecs = (isLongBreak ? cfg.long : cfg.short) * 60;
            flash(phaseInfo().flashColor);
            playAlarm(true);
        } else {
            phase = 'work';
            totalSecs = cfg.work * 60;
            flash(phaseInfo().flashColor);
            playAlarm(false);
        }
        
        remainSecs = totalSecs;
        updateUI();
        
        setTimeout(() => {
            startTimer();
        }, 1000);
    }
    
    document.getElementById('gdi-pom-fab').addEventListener('click', () => {
        panelOpen = !panelOpen;
        document.getElementById('gdi-pom-panel').classList.toggle('open', panelOpen);
    });
    
    document.addEventListener('click', e => {
        if (!root.contains(e.target) && panelOpen) {
            panelOpen = false;
            document.getElementById('gdi-pom-panel').classList.remove('open');
        }
    }, {capture: true});
    
    document.getElementById('gdi-pom-start').addEventListener('click', () => {
        running ? pauseTimer() : startTimer();
    });
    
    document.getElementById('gdi-pom-skip').addEventListener('click', nextPhase);
    document.getElementById('gdi-pom-reset').addEventListener('click', resetTimer);
    
    ['gdi-pom-c-work', 'gdi-pom-c-short', 'gdi-pom-c-long', 'gdi-pom-c-sess'].forEach(id => {
        document.getElementById(id).addEventListener('change', () => {
            cfg = {
                work: parseInt(document.getElementById('gdi-pom-c-work').value) || 25,
                short: parseInt(document.getElementById('gdi-pom-c-short').value) || 5,
                long: parseInt(document.getElementById('gdi-pom-c-long').value) || 15,
                sessions: parseInt(document.getElementById('gdi-pom-c-sess').value) || 4,
            };
            localStorage.setItem('gdi-pom-cfg', JSON.stringify(cfg));
            if (!running) {
                phase = 'work';
                totalSecs = cfg.work * 60;
                remainSecs = totalSecs;
                completedSessions = 0;
                updateUI();
            }
        });
    });
    
    function getVideoEl() {
        return document.querySelector('video');
    }
    
    function syncToPlayer(videoEl) {
        if (!videoEl || playerSynced) return;
        playerSynced = true;
        document.getElementById('gdi-pom-sync').textContent = '🔗 Sincronizado com o player';
        
        function onVideoPlay() {
            if (!running) startTimer();
        }
        
        function onVideoPause() {
            if (running) pauseTimer();
        }
        
        videoEl.addEventListener('play', onVideoPlay);
        videoEl.addEventListener('pause', onVideoPause);
        videoEl.addEventListener('ended', onVideoPause);
        
        if (window._gdiPlayerInstance) {
            const player = window._gdiPlayerInstance;
            if (typeof player.on === 'function') {
                player.on('play', onVideoPlay);
                player.on('pause', onVideoPause);
                player.on('ended', onVideoPause);
            }
        }
        
        const cleanupObserver = new MutationObserver(() => {
            if (!document.body.contains(videoEl)) {
                videoEl.removeEventListener('play', onVideoPlay);
                videoEl.removeEventListener('pause', onVideoPause);
                videoEl.removeEventListener('ended', onVideoPause);
                playerSynced = false;
                cleanupObserver.disconnect();
            }
        });
        cleanupObserver.observe(document.body, {childList: true, subtree: true});
    }
    
    const observer = new MutationObserver(() => {
        const vid = getVideoEl();
        if (vid && !playerSynced) syncToPlayer(vid);
        if (!vid) playerSynced = false;
    });
    observer.observe(document.body, {childList: true, subtree: true});
    
    const existingVid = getVideoEl();
    if (existingVid) syncToPlayer(existingVid);
    
    const domGuard = new MutationObserver(() => {
        if (!document.body.contains(root)) {
            document.body.appendChild(root);
            playerSynced = false;
            panelOpen = false;
            document.getElementById('gdi-pom-panel').classList.remove('open');
            updateUI();
        }
        if (!document.body.contains(flashEl)) {
            document.body.appendChild(flashEl);
        }
    });
    domGuard.observe(document.body, {childList: true});
    
    updateUI();
    console.log('[GDI Pomodoro] Inicializado ✓');
}

// ============================================================
// FUNÇÕES AUXILIARES FINAIS
// ============================================================
async function getCookie(i) {
    const e = i + "=";
    const t = document.cookie.split(";");
    for (let n = 0; n < t.length; n++) {
        let a = t[n];
        for (; a.charAt(0) == " "; ) a = a.substring(1);
        if (a.indexOf(e) == 0) return a.substring(e.length);
    }
    return null;
}

document.addEventListener("change", function(i) {
    i.target && i.target.id === "select-all-checkboxes" && document.querySelectorAll("input.gdi-row-check").forEach(t => {
        t.checked = i.target.checked;
    });
});

window.onpopstate = function() {
    render(window.location.pathname);
};

function fetchQuota() {
    const i = window.current_drive_order || 0;
    fetch(`/${i}:quota`).then(e => {
        if (!e.ok) throw new Error("quota fetch failed");
        return e.json();
    }).then(e => {
        const t = e.storageQuota;
        if (!t) return;
        const n = Number(t.usage || 0);
        const a = Number(t.limit || 0);
        const c = document.getElementById("gdi-quota-bar");
        const l = document.getElementById("gdi-quota-text");
        const d = document.getElementById("gdi-quota-fill");
        if (!c || !l || !d) return;
        
        const o = a > 0 ? Math.min(100, n / a * 100) : 0;
        const s = o > 90 ? "#f44336" : o > 70 ? "#ff9800" : "#4caf50";
        
        l.textContent = a > 0 ? `${formatFileSize(n)} used of ${formatFileSize(a)} (${o.toFixed(1)}%)` : `${formatFileSize(n)} used`;
        d.style.width = o + "%";
        d.style.background = s;
        c.style.display = "block";
    }).catch(() => {});
}

// ============================================================
// INICIALIZAÇÃO FINAL
// ============================================================
(function() {
    const e = localStorage.getItem("gdi-theme") || "dark";
    applyTheme(e);
})();

$(function() {
    init();
    
    if (window.UI?.debug_mode) {
        GDIDebug.attach();
    }
    
    GDIUserSystem.init();
    
    if (window.UI?.show_quota) {
        fetchQuota();
    }
    
    if (new URLSearchParams(window.location.search).get("embed") === "1") {
        document.body.classList.add("embed-mode");
    }
    
    render(window.location.pathname);
    initPomodoroOnce();
    
    console.log('[GDI] Aplicação inicializada com sucesso');
});

// Expor funções globalmente
window.toggleNotesPanel = toggleNotesPanel;
window.addVideoNote = addVideoNote;
window.deleteVideoNote = deleteVideoNote;
window.jumpToTimestamp = jumpToTimestamp;
window.resumeVideo = resumeVideo;
